-- Tallyard core schema.
-- Conventions: UUID primary keys generated by the application (UUIDv7 for index locality),
-- timestamptz everywhere, exact decimals for money and quantities, every tenant-owned row carries
-- tenant_id so isolation can be enforced in queries and verified in tests.

-- ---------------------------------------------------------------------------------------------
-- Tenancy
-- ---------------------------------------------------------------------------------------------
CREATE TABLE tenant (
    id          uuid PRIMARY KEY,
    name        text        NOT NULL,
    created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE api_key (
    id          uuid PRIMARY KEY,
    tenant_id   uuid        NOT NULL REFERENCES tenant (id),
    name        text        NOT NULL,
    prefix      varchar(16) NOT NULL,            -- public, shown in listings: "ty_live_ab12cd34"
    key_hash    varchar(64)    NOT NULL UNIQUE,     -- SHA-256 hex of the full key
    scopes      text[]      NOT NULL,            -- INGEST | READ | ADMIN
    created_at  timestamptz NOT NULL DEFAULT now(),
    revoked_at  timestamptz
);
CREATE INDEX api_key_tenant_idx ON api_key (tenant_id);

-- ---------------------------------------------------------------------------------------------
-- Catalog: meters, customers, plans, subscriptions
-- ---------------------------------------------------------------------------------------------
CREATE TABLE meter (
    id                 uuid PRIMARY KEY,
    tenant_id          uuid        NOT NULL REFERENCES tenant (id),
    code               varchar(64) NOT NULL,
    name               text        NOT NULL,
    event_type         varchar(64) NOT NULL,
    aggregation        varchar(16) NOT NULL CHECK (aggregation IN ('SUM','COUNT','MIN','MAX','LAST','UNIQUE_COUNT')),
    value_property     varchar(64),              -- NULL for COUNT
    unit               varchar(32) NOT NULL,
    acceptance_window_seconds bigint NOT NULL DEFAULT 3024000 CHECK (acceptance_window_seconds > 0), -- 35 days
    created_at         timestamptz NOT NULL DEFAULT now(),
    UNIQUE (tenant_id, code)
);
CREATE INDEX meter_tenant_event_type_idx ON meter (tenant_id, event_type);

CREATE TABLE customer (
    id           uuid PRIMARY KEY,
    tenant_id    uuid         NOT NULL REFERENCES tenant (id),
    external_id  varchar(128) NOT NULL,          -- the "subject" field of usage events
    name         text         NOT NULL,
    created_at   timestamptz  NOT NULL DEFAULT now(),
    UNIQUE (tenant_id, external_id)
);

CREATE TABLE plan (
    id               uuid PRIMARY KEY,
    tenant_id        uuid          NOT NULL REFERENCES tenant (id),
    code             varchar(64)   NOT NULL,
    name             text          NOT NULL,
    currency         varchar(3)      NOT NULL,
    interval_unit    varchar(8)    NOT NULL CHECK (interval_unit IN ('MINUTES','HOURS','DAYS','MONTHS')),
    interval_length  integer       NOT NULL CHECK (interval_length > 0),
    grace_seconds    integer       NOT NULL DEFAULT 3600 CHECK (grace_seconds >= 0),
    minimum_amount   numeric(19,6) NOT NULL DEFAULT 0 CHECK (minimum_amount >= 0),
    locked           boolean       NOT NULL DEFAULT false,   -- true once referenced by a subscription
    created_at       timestamptz   NOT NULL DEFAULT now(),
    UNIQUE (tenant_id, code)
);

CREATE TABLE plan_component (
    id              uuid PRIMARY KEY,
    plan_id         uuid          NOT NULL REFERENCES plan (id) ON DELETE CASCADE,
    meter_id        uuid          NOT NULL REFERENCES meter (id),
    position        integer       NOT NULL,
    pricing_model   varchar(16)   NOT NULL CHECK (pricing_model IN ('FLAT','PER_UNIT','GRADUATED','VOLUME','PACKAGE')),
    included_units  numeric(19,6) NOT NULL DEFAULT 0 CHECK (included_units >= 0),
    package_size    numeric(19,6) CHECK (package_size IS NULL OR package_size > 0),
    hard_limit      numeric(19,6) CHECK (hard_limit IS NULL OR hard_limit >= 0),
    UNIQUE (plan_id, meter_id),
    UNIQUE (plan_id, position)
);

CREATE TABLE price_tier (
    id            uuid PRIMARY KEY,
    component_id  uuid           NOT NULL REFERENCES plan_component (id) ON DELETE CASCADE,
    position      integer        NOT NULL,
    up_to         numeric(19,6),                 -- NULL = unbounded (last tier)
    unit_price    numeric(19,10) NOT NULL DEFAULT 0 CHECK (unit_price >= 0),
    flat_amount   numeric(19,6)  NOT NULL DEFAULT 0 CHECK (flat_amount >= 0),
    UNIQUE (component_id, position)
);

CREATE TABLE subscription (
    id           uuid PRIMARY KEY,
    tenant_id    uuid        NOT NULL REFERENCES tenant (id),
    customer_id  uuid        NOT NULL REFERENCES customer (id),
    plan_id      uuid        NOT NULL REFERENCES plan (id),
    starts_at    timestamptz NOT NULL,
    ends_at      timestamptz,
    status       varchar(16) NOT NULL CHECK (status IN ('ACTIVE','ENDED')),
    created_at   timestamptz NOT NULL DEFAULT now(),
    CHECK (ends_at IS NULL OR ends_at > starts_at)
);
CREATE INDEX subscription_customer_starts_idx ON subscription (customer_id, starts_at DESC);
-- At most one subscription per customer may be open-ended.
CREATE UNIQUE INDEX subscription_one_open_per_customer ON subscription (customer_id) WHERE ends_at IS NULL;

-- ---------------------------------------------------------------------------------------------
-- Billing periods and invoice drafts
-- ---------------------------------------------------------------------------------------------
CREATE TABLE billing_period (
    id               uuid PRIMARY KEY,
    tenant_id        uuid        NOT NULL REFERENCES tenant (id),
    subscription_id  uuid        NOT NULL REFERENCES subscription (id),
    customer_id      uuid        NOT NULL REFERENCES customer (id),
    starts_at        timestamptz NOT NULL,
    ends_at          timestamptz NOT NULL,
    state            varchar(16) NOT NULL CHECK (state IN ('OPEN','CLOSING','RATED','FINALIZED')),
    grace_until      timestamptz NOT NULL,
    rated_at         timestamptz,
    finalized_at     timestamptz,
    version          bigint      NOT NULL DEFAULT 0,
    created_at       timestamptz NOT NULL DEFAULT now(),
    UNIQUE (subscription_id, starts_at),
    CHECK (ends_at > starts_at)
);
-- Exactly one OPEN period per subscription.
CREATE UNIQUE INDEX billing_period_one_open ON billing_period (subscription_id) WHERE state = 'OPEN';
-- Scheduler scans: periods due for closing / rating.
CREATE INDEX billing_period_state_due_idx ON billing_period (state, ends_at);
CREATE INDEX billing_period_state_grace_idx ON billing_period (state, grace_until);
CREATE INDEX billing_period_customer_idx ON billing_period (customer_id, starts_at DESC);

CREATE TABLE invoice_draft (
    id                    uuid PRIMARY KEY,
    tenant_id             uuid          NOT NULL REFERENCES tenant (id),
    period_id             uuid          NOT NULL UNIQUE REFERENCES billing_period (id),
    customer_id           uuid          NOT NULL REFERENCES customer (id),
    currency              varchar(3)      NOT NULL,
    subtotal              numeric(19,6) NOT NULL,
    credits_applied       numeric(19,6) NOT NULL DEFAULT 0,
    total                 numeric(19,6) NOT NULL,
    reproducibility_hash  varchar(64)      NOT NULL,
    created_at            timestamptz   NOT NULL DEFAULT now(),
    CHECK (credits_applied >= 0 AND total >= 0)
);

CREATE TABLE invoice_line (
    id            uuid PRIMARY KEY,
    invoice_id    uuid          NOT NULL REFERENCES invoice_draft (id) ON DELETE CASCADE,
    position      integer       NOT NULL,
    kind          varchar(24)   NOT NULL CHECK (kind IN ('USAGE','ADJUSTMENT','MINIMUM_COMMITMENT')),
    component_id  uuid          REFERENCES plan_component (id),
    meter_id      uuid          REFERENCES meter (id),
    description   text          NOT NULL,
    quantity      numeric(19,6) NOT NULL,
    amount        numeric(19,6) NOT NULL,
    breakdown     jsonb         NOT NULL,        -- tier-by-tier explanation
    UNIQUE (invoice_id, position)
);

-- ---------------------------------------------------------------------------------------------
-- Metering: immutable event log, hourly buckets, adjustments, rejections
-- ---------------------------------------------------------------------------------------------
CREATE TABLE usage_event (
    id           uuid PRIMARY KEY,
    tenant_id    uuid          NOT NULL REFERENCES tenant (id),
    event_id     varchar(128)  NOT NULL,         -- client idempotency key
    event_type   varchar(64)   NOT NULL,
    subject      varchar(128)  NOT NULL,
    occurred_at  timestamptz   NOT NULL,
    ingested_at  timestamptz   NOT NULL,
    properties   jsonb         NOT NULL DEFAULT '{}'::jsonb,
    -- The deduplication guarantee: a second insert with the same identity is a no-op.
    UNIQUE (tenant_id, event_id)
);
CREATE INDEX usage_event_subject_time_idx ON usage_event (tenant_id, subject, occurred_at);
CREATE INDEX usage_event_type_time_idx ON usage_event (tenant_id, event_type, occurred_at);

CREATE TABLE meter_bucket (
    tenant_id         uuid          NOT NULL REFERENCES tenant (id),
    period_id         uuid          NOT NULL REFERENCES billing_period (id),
    meter_id          uuid          NOT NULL REFERENCES meter (id),
    customer_id       uuid          NOT NULL REFERENCES customer (id),
    bucket_start      timestamptz   NOT NULL,    -- truncated to the hour; buckets never straddle periods
    agg_sum           numeric(19,6) NOT NULL DEFAULT 0,
    agg_count         bigint        NOT NULL DEFAULT 0,
    agg_min           numeric(19,6),
    agg_max           numeric(19,6),
    agg_last          numeric(19,6),
    last_occurred_at  timestamptz,
    PRIMARY KEY (period_id, meter_id, customer_id, bucket_start)
);
CREATE INDEX meter_bucket_customer_time_idx ON meter_bucket (customer_id, bucket_start);

CREATE TABLE usage_adjustment (
    id                  uuid PRIMARY KEY,
    tenant_id           uuid          NOT NULL REFERENCES tenant (id),
    subscription_id     uuid          NOT NULL REFERENCES subscription (id),
    applied_period_id   uuid          NOT NULL REFERENCES billing_period (id),
    original_period_id  uuid          REFERENCES billing_period (id),
    meter_id            uuid          NOT NULL REFERENCES meter (id),
    usage_event_id      uuid          NOT NULL REFERENCES usage_event (id),
    value               numeric(19,6) NOT NULL,
    occurred_at         timestamptz   NOT NULL,
    created_at          timestamptz   NOT NULL DEFAULT now(),
    UNIQUE (usage_event_id, meter_id)
);
CREATE INDEX usage_adjustment_applied_idx ON usage_adjustment (applied_period_id);

CREATE TABLE rejected_event (
    id           uuid PRIMARY KEY,
    tenant_id    uuid         NOT NULL REFERENCES tenant (id),
    event_id     varchar(128),
    event_type   varchar(64),
    subject      varchar(128),
    occurred_at  timestamptz,
    reason       varchar(40)  NOT NULL,     -- see io.tallyard.metering.RejectionReason
    detail       text,
    payload      jsonb,
    created_at   timestamptz  NOT NULL DEFAULT now()
);
CREATE INDEX rejected_event_tenant_time_idx ON rejected_event (tenant_id, created_at DESC);

-- ---------------------------------------------------------------------------------------------
-- Prepaid credits
-- ---------------------------------------------------------------------------------------------
CREATE TABLE credit_grant (
    id               uuid PRIMARY KEY,
    tenant_id        uuid          NOT NULL REFERENCES tenant (id),
    customer_id      uuid          NOT NULL REFERENCES customer (id),
    currency         varchar(3)      NOT NULL,
    amount_granted   numeric(19,6) NOT NULL CHECK (amount_granted > 0),
    amount_consumed  numeric(19,6) NOT NULL DEFAULT 0,
    priority         integer       NOT NULL DEFAULT 0,
    expires_at       timestamptz,
    created_at       timestamptz   NOT NULL DEFAULT now(),
    -- The invariant the application must never be able to violate, even under concurrency.
    CHECK (amount_consumed >= 0 AND amount_consumed <= amount_granted)
);
CREATE INDEX credit_grant_customer_idx ON credit_grant (customer_id, expires_at, priority);

CREATE TABLE credit_ledger_entry (
    id          uuid PRIMARY KEY,
    grant_id    uuid          NOT NULL REFERENCES credit_grant (id),
    invoice_id  uuid          NOT NULL REFERENCES invoice_draft (id),
    amount      numeric(19,6) NOT NULL CHECK (amount > 0),
    created_at  timestamptz   NOT NULL DEFAULT now()
);
CREATE INDEX credit_ledger_invoice_idx ON credit_ledger_entry (invoice_id);

-- ---------------------------------------------------------------------------------------------
-- Transactional outbox and webhooks
-- ---------------------------------------------------------------------------------------------
CREATE TABLE outbox_event (
    id               uuid PRIMARY KEY,
    tenant_id        uuid        NOT NULL REFERENCES tenant (id),
    aggregate_type   varchar(32) NOT NULL,
    aggregate_id     uuid        NOT NULL,
    event_type       varchar(64) NOT NULL,
    payload          jsonb       NOT NULL,
    created_at       timestamptz NOT NULL DEFAULT now(),
    attempts         integer     NOT NULL DEFAULT 0,
    next_attempt_at  timestamptz NOT NULL DEFAULT now(),
    published_at     timestamptz
);
-- Publisher scans only unpublished rows; keep that index small with a partial index.
CREATE INDEX outbox_event_pending_idx ON outbox_event (next_attempt_at, created_at) WHERE published_at IS NULL;

CREATE TABLE webhook_endpoint (
    id                uuid PRIMARY KEY,
    tenant_id         uuid        NOT NULL REFERENCES tenant (id),
    url               text        NOT NULL,
    secret_encrypted  text        NOT NULL,       -- AES-GCM, key from TALLYARD_ENCRYPTION_KEY
    event_types       text[]      NOT NULL,
    active            boolean     NOT NULL DEFAULT true,
    created_at        timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX webhook_endpoint_tenant_idx ON webhook_endpoint (tenant_id) WHERE active;

CREATE TABLE webhook_delivery (
    id               uuid PRIMARY KEY,
    tenant_id        uuid        NOT NULL REFERENCES tenant (id),
    endpoint_id      uuid        NOT NULL REFERENCES webhook_endpoint (id),
    outbox_event_id  uuid        NOT NULL,
    event_type       varchar(64) NOT NULL,
    payload          jsonb       NOT NULL,
    state            varchar(16) NOT NULL CHECK (state IN ('PENDING','DELIVERED','DEAD')),
    attempts         integer     NOT NULL DEFAULT 0,
    next_attempt_at  timestamptz NOT NULL DEFAULT now(),
    last_status      integer,
    last_error       text,
    created_at       timestamptz NOT NULL DEFAULT now(),
    delivered_at     timestamptz,
    -- The same outbox event is delivered to the same endpoint at most once (consumer idempotency).
    UNIQUE (endpoint_id, outbox_event_id)
);
CREATE INDEX webhook_delivery_due_idx ON webhook_delivery (next_attempt_at) WHERE state = 'PENDING';
CREATE INDEX webhook_delivery_tenant_idx ON webhook_delivery (tenant_id, created_at DESC);
